class RandomizedSetBrute {
public:
    vector<int> arr;

    bool insert(int val) {
        if (find(arr.begin(), arr.end(), val) != arr.end()) return false;  // linear scan
        arr.push_back(val);
        return true;
    }

    bool remove(int val) {
        auto it = find(arr.begin(), arr.end(), val);
        if (it == arr.end()) return false;
        arr.erase(it);                                    // linear scan + O(n) shift
        return true;
    }

    int getRandom() {
        return arr[rand() % arr.size()];
    }
};

