import random

class RandomizedSet:
    def __init__(self):
        self.arr = []
        self.idx = {}                                # value -> index in arr

    def insert(self, val):
        if val in self.idx:
            return False
        self.idx[val] = len(self.arr)
        self.arr.append(val)
        return True

    def remove(self, val):
        if val not in self.idx:
            return False
        i = self.idx[val]
        last = self.arr[-1]
        self.arr[i] = last                            # move last element into the removed slot
        self.idx[last] = i
        self.arr.pop()                                  # O(1) pop from the end
        del self.idx[val]
        return True

    def get_random(self):
        return random.choice(self.arr)

