import java.util.*;

class RandomizedSet {
    List<Integer> arr = new ArrayList<>();
    Map<Integer, Integer> idx = new HashMap<>();       // value -> index in arr
    Random rand = new Random();

    boolean insert(int val) {
        if (idx.containsKey(val)) return false;
        idx.put(val, arr.size());
        arr.add(val);
        return true;
    }

    boolean remove(int val) {
        if (!idx.containsKey(val)) return false;
        int i = idx.get(val);
        int last = arr.get(arr.size() - 1);
        arr.set(i, last);                                  // move last element into the removed slot
        idx.put(last, i);
        arr.remove(arr.size() - 1);                          // O(1) pop from the end
        idx.remove(val);
        return true;
    }

    int getRandom() {
        return arr.get(rand.nextInt(arr.size()));
    }
}

